def intersection(interval1, interval2):
    def is_prime(num):
        if num <= 1:
            return False
        if num == 2:
            return True
        for i in range(2, int(num ** 0.5) + 1):
            if num % i == 0:
                return False
        return True

    # Determine the overlapping interval (inclusive)
    l = max(interval1[0], interval2[0])
    r = min(interval1[1], interval2[1])

    # No overlap
