        return "NO"

    # Check for any prime integer within the overlapping range
    start = int(l) if l == int(l) else int(l) + 1  # smallest integer >= l
    end = int(r)  # largest integer <= r

    for num in range(start, end + 1):
        if is_prime(num):
            return "YES"
    return "NO"
